 subprocess.run([java,'-jar',str(root/'audio/tooling/ecj.jar'),'-1.8','-nowarn','-d',folder,*files,str(root/'shared/multiroom/bridge-src/com/wallpanel/bridge/AppBluetoothProfile.java')],check=True)
